#!/data/data/com.termux/files/usr/bin/bash
set -Eeuo pipefail
cd "$HOME/companyos"
source "$HOME/.companyos_launch_env" 2>/dev/null || true

STAMP="$(date +%Y%m%d_%H%M%S)"
BK="$HOME/companyos/.companyos_backups/evidence_decision_v20_$STAMP"
mkdir -p "$BK"
cp -a companyos/runtime/profit_first_dispatcher.py "$BK/" 2>/dev/null || true
cp -a companyos/runtime/service_supervisor.py "$BK/" 2>/dev/null || true

echo "" | base64 -d > companyos/runtime/evidence_decision_closure.py

echo "" | base64 -d > "$PREFIX/tmp/companyos_decision_dispatch_patch.py"
python "$PREFIX/tmp/companyos_decision_dispatch_patch.py"
rm -f "$PREFIX/tmp/companyos_decision_dispatch_patch.py"

echo "" | base64 -d > "$PREFIX/tmp/companyos_decision_supervisor_patch.py"
python "$PREFIX/tmp/companyos_decision_supervisor_patch.py"
rm -f "$PREFIX/tmp/companyos_decision_supervisor_patch.py"

echo "" | base64 -d > scripts/companyos_decisionctl
chmod +x scripts/companyos_decisionctl
echo "" | base64 -d > tests/test_evidence_decision_closure_v20.py

echo "[1/9] Compile"
python -m py_compile companyos/runtime/evidence_decision_closure.py companyos/runtime/profit_first_dispatcher.py companyos/runtime/service_supervisor.py tests/test_evidence_decision_closure_v20.py

echo "[2/9] Decision closure tests"
python -m unittest tests.test_evidence_decision_closure_v20 -v

echo "[3/9] Refresh evidence state"
scripts/companyos_evidencectl once || true

echo "[4/9] Evaluate evidence-to-decision closure"
scripts/companyos_decisionctl once | tee .companyos_runtime/evidence_decision_v20_first_cycle.json || true

echo "[5/9] Show decision status"
scripts/companyos_decisionctl status || true

echo "[6/9] Verify dispatcher sees closure"
python - <<'PY'
from companyos.runtime.profit_first_dispatcher import build_goal
g=build_goal()
print("DECISION_CLOSURE_PRESENT=", "EVIDENCE-TO-DECISION CLOSURE" in g)
print("GOAL_LENGTH=",len(g))
PY

echo "[7/9] Commit/push"
git add companyos/runtime/evidence_decision_closure.py companyos/runtime/profit_first_dispatcher.py companyos/runtime/service_supervisor.py scripts/companyos_decisionctl tests/test_evidence_decision_closure_v20.py
git diff --cached --quiet || git commit -m "Close evidence loop into guarded opportunity decisions"
BRANCH="$(git branch --show-current)"
[ -n "$BRANCH" ] && git push origin "$BRANCH" || true

echo "[8/9] Restart"
scripts/companyosctl restart || true
sleep 8

echo "[9/9] Verify"
echo "===== DECISION CLOSURE ====="
scripts/companyos_decisionctl status || true
echo "===== EVIDENCE ====="
scripts/companyos_evidencectl status || true
echo "===== ACTION BRIDGE ====="
scripts/companyos_actionbridgectl status || true
echo "===== OUTCOME LEARNING ====="
scripts/companyos_outcomectl status || true
echo "===== SERVICES ====="
scripts/companyosctl status || true

echo "BACKUP=$BK"
echo "COMPANYOS_EVIDENCE_TO_DECISION_CLOSURE_V20=PASS"
